const { getDefaultConfig } = require('expo/metro-config');
const fs = require('fs');
const path = require('path');

const config = getDefaultConfig(__dirname);

// lucide-react-native's index re-exports all ~1,700 icons (≈1.8 MB of source) and Metro can't tree-shake it.
// Bundle only the icons the app actually imports: scan the sources once per Metro start and point
// `import { X } from 'lucide-react-native'` at a generated file that re-exports just those icons.
const LITE = path.join(__dirname, '.lucide-lite.js');
function writeLucideLite() {
  try {
    const pkg = path.join(__dirname, 'node_modules/lucide-react-native/dist/esm/lucide-react-native.mjs');
    const idx = fs.readFileSync(pkg, 'utf8');
    const file = {};
    for (const m of idx.matchAll(/export \{([^}]*)\} from '\.\/icons\/([^']+)\.mjs'/g)) {
      for (const part of m[1].split(',')) file[part.trim().split(' as ').pop().trim()] = m[2];
    }
    const names = new Set();
    const walk = (dir) => {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, e.name);
        if (e.isDirectory()) walk(p);
        else if (/\.(tsx?|jsx?)$/.test(e.name)) {
          const s = fs.readFileSync(p, 'utf8');
          for (const m of s.matchAll(/import\s*(type\s*)?\{([^}]*)\}\s*from\s*'lucide-react-native'/g)) {
            if (m[1]) continue;
            for (const part of m[2].split(',')) {
              const n = part.trim();
              if (n && !n.startsWith('type ')) names.add(n.split(' as ')[0].trim());
            }
          }
        }
      }
    };
    walk(path.join(__dirname, 'src'));
    const lines = [];
    for (const n of [...names].sort()) {
      // an unknown name falls back to the full package, so nothing can silently go missing
      lines.push(file[n] ? `export { default as ${n} } from 'lucide-react-native/icons/${file[n]}';` : `export { ${n} } from 'lucide-react-native/full';`);
    }
    fs.writeFileSync(LITE, `// generated by metro.config.js — do not edit\n${lines.join('\n')}\n`);
    return true;
  } catch (e) {
    console.warn('lucide-lite: using the full icon package', e?.message);
    return false;
  }
}
const lite = writeLucideLite();

// The phone's 3D view runs MapLibre in a web view from one bundle. Its usual build makes its worker from its own
// minified source, which breaks once Metro minifies it again, so the view uses the CSP build and gets the worker as a
// plain string (generated here, untouched by the minifier) to start from a blob.
const WORKER = path.join(__dirname, '.maplibre-worker.js');
try {
  const src = fs.readFileSync(path.join(__dirname, 'node_modules/maplibre-gl/dist/maplibre-gl-csp-worker.js'), 'utf8');
  fs.writeFileSync(WORKER, `// generated by metro.config.js — do not edit\nexport default ${JSON.stringify(src)};\n`);
} catch (e) {
  console.warn('maplibre worker: not generated', e?.message);
}

const resolve = config.resolver.resolveRequest;
config.resolver.resolveRequest = (ctx, name, platform) => {
  if (platform === 'web' && name === 'react-native-maps') return { type: 'sourceFile', filePath: path.join(__dirname, 'src/components/map/webMaps.tsx') };
  if (name === 'lucide-react-native' && lite && ctx.originModulePath !== LITE) return { type: 'sourceFile', filePath: LITE };
  if (name === 'lucide-react-native/full') return (resolve ?? ctx.resolveRequest)(ctx, 'lucide-react-native', platform);
  return (resolve ?? ctx.resolveRequest)(ctx, name, platform);
};
module.exports = config;
